  yadm_nm VARCHAR(400) NULL COMMENT '요양기관명칭',
  ykiho VARCHAR(8) NULL COMMENT '요양기관기호',
  itm_nm VARCHAR(400) NULL COMMENT '제품명(표준코드명칭)',
  msup_std_cd VARCHAR(13) NULL COMMENT '제품코드(표준코드)',
  model_nm VARCHAR(400) NULL COMMENT '모델명(의료기기)',
  perm_cert_rpt_no VARCHAR(30) NULL COMMENT '허가·인증 또는 신고번호(의료기기)',
  pack_unit BIGINT NULL COMMENT '포장내총수량(규격)',
  offr_qty BIGINT NULL COMMENT '제공수량',
  tot_offr_qty BIGINT NULL COMMENT '계 = 포장내총수량 × 제공수량',
  offr_dd VARCHAR(8) NULL COMMENT '제공일자 yyyyMMdd',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_form_sample_offr_submission (submission_id),
  CONSTRAINT fk_form_sample_offr_submission FOREIGN KEY (submission_id)
    REFERENCES report_submission(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='견본품 제공 서식정보';

